<script setup lang="ts">import {Head,router,useForm} from '@inertiajs/vue3';import AdminLayout from '@core/Layouts/AdminLayout.vue';
import PageHeader from '@core/Components/PageHeader.vue';import {Button} from '@/components/ui/button';import {Input} from '@/components/ui/input';import {Label} from '@/components/ui/label';import DataTable,{type DataTableColumn} from '@core/Components/DataTable.vue';import type {Paginator} from '@core/types';defineProps<{settlements:Paginator<any>;gratuityPolicies:any[]}>();const policy=useForm({name:'Default gratuity',minimum_service_years:5,days_per_service_year:30,calculation_base:'basic'});function savePolicy(){policy.post(route('payroll.settlements.gratuity-policies.store'))}function post(routeName:string,id:number){router.post(route(routeName,id),{},{preserveScroll:true})}const columns:DataTableColumn[]=[{key:'employee_id',label:'Employee'},{key:'last_working_date',label:'Last day'},{key:'gross_due',label:'Gross due',align:'right'},{key:'gratuity_amount',label:'Gratuity',align:'right'},{key:'deductions',label:'Deductions',align:'right'},{key:'net_settlement',label:'Net',align:'right'},{key:'status',label:'Status'},{key:'actions',label:'',align:'right',exportable:false}];</script><template><AdminLayout :breadcrumbs="[{ title: 'Payroll' }, { title: 'Final settlements' }]"><Head title="Final settlements"/><PageHeader title="Final settlements" description="Prorated salary, gratuity policy, leave encashment and approved deductions." :icon="LayoutDashboard" :actions="[{ label:'New settlement', route:'payroll.settlements.create', icon: Plus }]"><div class="mt-5 grid gap-5 xl:grid-cols-[1fr_340px]"><DataTable route-name="payroll.settlements.index" title="Final settlements" :columns="columns" :rows="settlements.data" :meta="settlements.meta"><template #cell-employee_id="{row}"><strong>{{row.employee_name||row.employee_id}}</strong><span class="block text-xs text-muted-foreground">{{row.employee_id}}</span><details v-if="row.breakdown_json?.manual_adjustments" class="mt-1 text-xs"><summary class="cursor-pointer text-primary">Review calculation & manual inputs</summary><div class="mt-2 space-y-1"><p v-for="(segment,i) in row.breakdown_json.salary_proration?.salary_segments||[]" :key="i">{{segment.from}}–{{segment.to}} · {{segment.days}} days · gross {{Number(segment.gross_salary).toLocaleString()}}</p><p>Leave encashment: {{row.breakdown_json.manual_adjustments.leave_encashment_reason||'No reason entered'}}</p><p>Other benefits: {{row.breakdown_json.manual_adjustments.other_benefits_reason||'No reason entered'}}</p><p>Deductions: {{row.breakdown_json.manual_adjustments.deductions_reason||'No reason entered'}}</p></div></details></template><template #cell-gross_due="{row}">{{Number(row.gross_due).toLocaleString()}}</template><template #cell-gratuity_amount="{row}">{{Number(row.gratuity_amount).toLocaleString()}}</template><template #cell-deductions="{row}">{{Number(row.deductions).toLocaleString()}}</template><template #cell-net_settlement="{row}"><strong>{{Number(row.net_settlement).toLocaleString()}}</strong></template><template #cell-status="{row}">{{row.status}}</template><template #cell-actions="{row}"><Button v-if="row.status==='pending'" size="sm" @click="post('payroll.settlements.approve',Number(row.id))">Approve</Button><Button v-if="row.status==='approved'" size="sm" @click="post('payroll.settlements.paid',Number(row.id))">Mark paid</Button></template></DataTable><aside class="h-fit rounded-xl border bg-card p-5"><h2 class="font-semibold">Gratuity policy</h2><form @submit.prevent="savePolicy" class="mt-3 space-y-3"><div><Label>Policy name</Label><Input v-model="policy.name"/></div><div><Label>Minimum service years</Label><Input v-model.number="policy.minimum_service_years" type="number" min="0"/></div><div><Label>Days per service year</Label><Input v-model.number="policy.days_per_service_year" type="number" min="0"/></div><div><Label>Salary base</Label><select v-model="policy.calculation_base" class="h-10 w-full rounded-md border bg-background px-3"><option value="basic">Basic</option><option value="gross">Gross</option></select></div><Button :disabled="policy.processing">Save policy</Button></form><div class="mt-4 border-t pt-3"><p v-for="x in gratuityPolicies" :key="x.id" class="py-1 text-xs text-muted-foreground">{{x.name}} · {{x.minimum_service_years}}y · {{x.days_per_service_year}} days</p></div></aside></div>    </PageHeader>
  </AdminLayout></template>